export type ShortwinSimplePluginPdas = {
  config: typeof findConfigPda;
  exposure: typeof findExposurePda;
  receipt: typeof findReceiptPda;
  market: typeof findMarketPda;
  tokenVault: typeof findTokenVaultPda;
  pool: typeof findPoolPda;
  rollPoolTokenVault: typeof findRollPoolTokenVaultPda;
};

export type ShortwinSimplePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function shortwinSimpleProgram() {
  return <T extends ShortwinSimplePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { shortwinSimple: ShortwinSimplePlugin }> => {
    return extendClient(client, {
      shortwinSimple: {
        accounts: {
          config: addSelfFetchFunctions(client, getConfigCodec()),
          exposure: addSelfFetchFunctions(client, getExposureCodec()),
          lenderReceipt: addSelfFetchFunctions(client, getLenderReceiptCodec()),
          loan: addSelfFetchFunctions(client, getLoanCodec()),
          market: addSelfFetchFunctions(client, getMarketCodec()),
          policy: addSelfFetchFunctions(client, getPolicyCodec()),
          poolGeneration: addSelfFetchFunctions(
            client,
            getPoolGenerationCodec(),
          ),
          priceReference: addSelfFetchFunctions(
            client,
            getPriceReferenceCodec(),
          ),
        },
        instructions: {
          addMargin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAddMarginInstructionAsync(input),
            ),
          armLiquidation: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getArmLiquidationInstructionAsync(input),
            ),
          claimSol: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimSolInstructionAsync(input),
            ),
          closePosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClosePositionInstructionAsync(input),
            ),
          defaultLoan: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDefaultLoanInstructionAsync(input),
            ),
          deposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync(input),
            ),
          forceExit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getForceExitInstructionAsync(input),
            ),
          initialize: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeInstructionAsync(input),
            ),
          newPolicy: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getNewPolicyInstructionAsync(input),
            ),
          openPosition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenPositionInstructionAsync(input),
            ),
          publishReference: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPublishReferenceInstructionAsync(input),
            ),
          registerMarket: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterMarketInstructionAsync(input),
            ),
          repay: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRepayInstructionAsync(input),
            ),
          reviewJupiter: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReviewJupiterInstructionAsync(input),
            ),
          rollPool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRollPoolInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          setPause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPauseInstructionAsync(input),
            ),
          setReporter: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetReporterInstructionAsync(input),
            ),
          withdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          exposure: findExposurePda,
          receipt: findReceiptPda,
          market: findMarketPda,
          tokenVault: findTokenVaultPda,
          pool: findPoolPda,
          rollPoolTokenVault: findRollPoolTokenVaultPda,
        },
        identifyAccount: identifyShortwinSimpleAccount,
        identifyInstruction: identifyShortwinSimpleInstruction,
        parseInstruction: parseShortwinSimpleInstruction,
      } as ShortwinSimplePlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
